import { mkdir, writeFile, readFile, copyFile, chmod } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import path from 'node:path';
const platforms={ 'win32-x64':'win32-amd64', 'darwin-arm64':'darwin-arm64', 'darwin-x64':'darwin-amd64', 'linux-x64':'linux-amd64', 'linux-arm64':'linux-arm64' };
const target=platforms[`${process.platform}-${process.arch}`];
if(!target)throw Error('Unsupported development platform');
const pkg=`@foundry-rs/anvil-${target}`,version='1.7.1';
const metadata=await(await fetch(`https://registry.npmjs.org/${pkg}/${version}`)).json();
const bytes=Buffer.from(await(await fetch(metadata.dist.tarball)).arrayBuffer());
if('sha512-'+createHash('sha512').update(bytes).digest('base64')!==metadata.dist.integrity)throw Error('Integrity verification failed');
const dir=path.resolve('runtime','download'); await mkdir(dir,{recursive:true});
await writeFile(path.join(dir,'anvil.tgz'),bytes);
const unpack=spawnSync('tar',['-xzf',path.join(dir,'anvil.tgz'),'-C',dir],{stdio:'inherit',windowsHide:true});
if(unpack.status!==0)throw Error('tar extraction failed; install a tar utility');
const binary=process.platform==='win32'?'anvil.exe':'anvil';
await copyFile(path.join(dir,'package','bin',binary),path.resolve('runtime',binary));
await chmod(path.resolve('runtime',binary),0o755);
await writeFile('runtime/download-provenance.json',JSON.stringify({package:pkg,version,url:metadata.dist.tarball,integrity:metadata.dist.integrity},null,2));
console.log('Verified and installed local Anvil '+version);
